/* ---------- aksi ---------- */
const A = {
  go(v) { view = v; render(); window.scrollTo(0, 0); },
  pick(pid, v) { sel.pid = pid; if (v) view = v; render(); },
  setRole(r) { sel.role = r; render(); },
  login(e) { e.preventDefault(); const role = sel.role || 'owner', pw = $('#pw').value; run(async () => { const u = await API.login(role, pw); view = 'home'; return u; }, (u) => 'Selamat datang, ' + u.name); },
  logout() { API.logout().then(() => { S = null; view = 'home'; render(); }); },
  setPass(e) { e.preventDefault(); const o = $('#pw0').value, n = $('#pw1').value; run(() => API.password(o, n), 'Password diganti'); },
  absen(type) { const f = $('#selfie').files[0]; if (!f) return toast('Ambil selfie dulu', true); const workers = Number($('#workers').value) || 0; const btn = $('#btnAbsen'); btn.disabled = true; btn.textContent = 'Mengirim…'; run(async () => { const loc = await getLoc(); const r = await API.absen(Object.assign({ projectId: sel.pid, type, file: f, workers }, loc || {})); view = 'home'; return r; }, (r) => r.onSite ? 'Absen ' + type + ' tercatat di lokasi' : r.distM == null ? 'Absen tercatat tanpa lokasi (GPS mati)' : 'Absen tercatat, tapi ' + r.distM + ' m dari proyek'); },
  step(i, d) { const p = P(); sel.prog = sel.prog || {}; const cur = sel.prog[i] != null ? sel.prog[i] : p.divisions[i].progress; sel.prog[i] = Math.max(0, Math.min(100, cur + d)); render(); },
  lapor() { const files = Array.from($('#fotos').files); if (!files.length) return toast('Minimal 1 foto pekerjaan', true); const p = P(); const items = Object.keys(sel.prog || {}).map((i) => ({ div: Number(i), pct: sel.prog[i] })).filter((it) => it.pct !== p.divisions[it.div].progress); if (!items.length) return toast('Belum ada perubahan progres', true); const note = $('#catatan').value; $('#btnLapor').disabled = true; run(async () => { await API.report({ projectId: sel.pid, items, note, files }); sel.prog = {}; view = 'home'; }, 'Laporan terkirim'); },
  nota() { const f = $('#fnota').files[0]; if (!f) return toast('Foto nota wajib', true); const b = { projectId: sel.pid, type: sel.ntype || 'material', desc: $('#desc').value, shop: $('#shop').value, amount: Number(String($('#amount').value).replace(/\D/g, '')), qty: Number($('#qty').value) || null, unitKey: $('#ukey').value || null, file: f }; if (!b.amount) return toast('Isi nominal', true); $('#btnNota').disabled = true; run(async () => { await API.nota(b); view = 'home'; }, 'Nota terkirim, menunggu Admin'); },
  setNType(t) { sel.ntype = t; render(); },
  decide(id, decision) { let note = ''; if (decision === 'reject') { note = prompt('Alasan menolak (dikirim ke mandor):'); if (note == null) return; } run(() => API.decide(id, decision, note), (s) => s === 'owner' ? 'Diteruskan ke Owner' : s === 'approved' ? 'Disetujui' : 'Ditolak'); },
  verify(reportId) { run(() => API.verify(sel.pid, reportId), 'Progres diverifikasi'); },
  saveRab() { const p = P(); const divisions = p.divisions.map((d, i) => ({ name: $('#dn' + i).value, rap: Number(String($('#dr' + i).value).replace(/\D/g, '')), progress: d.progress, verified: d.verified })); if (sel.newDiv) divisions.push({ name: sel.newDiv, rap: 0 }); const b = { id: p.id, name: $('#pname').value, client: $('#pclient').value, address: $('#paddr').value, lat: $('#plat').value, lng: $('#plng').value, buk: Number($('#buk').value), kasAwal: Number(String($('#kas').value).replace(/\D/g, '')), status: $('#pstatus').value, divisions }; run(async () => { await API.saveProject(b); sel.newDiv = null; }, 'RAB disimpan'); },
  addDiv() { sel.newDiv = prompt('Nama pekerjaan baru:'); if (sel.newDiv) A.saveRab(); },
  newProject() { const name = prompt('Nama proyek baru:'); if (!name) return; run(async () => { const p = await API.saveProject({ name, client: '', status: 'penawaran', buk: 15, divisions: ['Persiapan', 'Tanah & pondasi', 'Struktur beton', 'Dinding', 'Atap', 'Lantai & finishing'].map((n) => ({ name: n, rap: 0 })) }); sel.pid = p.id; view = 'rab'; }); },
  bukPreview() { const p = P(), C = S.config; const rap = p.divisions.reduce((a, d) => a + Number(String($('#dr' + d.id).value).replace(/\D/g, '')), 0); const buk = Number($('#buk').value); const cut = C.overhead + C.bunga + C.pph; const K = rap * (1 + buk / 100); const net = K ? (K - rap - K * cut) / K : 0; const z = buk < p.summary.floorBuk ? 'Rugi' : net < 0.05 ? 'Tipis' : buk > 20 ? 'Di atas wajar' : 'Aman'; $('#bukOut').innerHTML = 'Harga ke klien <b>' + sh(K) + '</b> · laba bersih <b>' + pct(net) + '</b> ' + pill(z, zoneCls(z)); },
  saveMx(key) { const patch = { low: Number($('#ml-' + key).value), typ: Number($('#mt-' + key).value), high: Number($('#mh-' + key).value), src: $('#ms-' + key).value }; run(() => API.matrix(key, patch), 'Matriks diperbarui'); },
  invoice(t) { run(() => API.invoice(sel.pid, t), (inv) => 'Tagihan dibuat: ' + rp(inv.transfer)); },
  paid(id) { if (!confirm('Tandai sudah dibayar klien?')) return; run(() => API.paid(id)); },
  vo() { const b = { projectId: sel.pid, kind: sel.voKind || 'plus', desc: $('#voDesc').value, cost: Number(String($('#voCost').value).replace(/\D/g, '')), margin: Number($('#voMargin').value), status: $('#voRisk').checked ? 'risk' : 'wait' }; if (!b.desc) return toast('Isi uraian pekerjaan', true); run(() => API.vo(b), 'Tambah-kurang dicatat. Kirim ke klien untuk persetujuan.'); },
  setVoKind(k) { sel.voKind = k; render(); },
  voStatus(id, status) { let by = ''; if (status === 'ok') { by = prompt('Disetujui oleh siapa? (nama & jabatan di pihak klien)'); if (by == null) return; } run(() => API.voStatus(id, status, by), status === 'ok' ? 'Disetujui klien — nilai kontrak diperbarui' : 'Status diperbarui'); },
  exportCsv() { const p = P(), s = p.summary; const lines = [['Buku Proyek — ' + p.name], ['Klien', p.client], [], ['Pekerjaan', 'RAP', 'Harga ke klien', 'Progres lapor', 'Progres verifikasi']]; p.divisions.forEach((d) => lines.push([d.name, d.rap, d.rap * (1 + p.buk / 100), d.progress + '%', d.verified + '%'])); lines.push([], ['Nilai kontrak', s.contract], ['RAP', s.rap], ['Biaya disetujui', s.spent], ['Kas', s.kas], ['Pendapatan diakui (PSAK 72)', s.revenue], ['Proyeksi laba bersih', s.labaAkhir]); const csv = '﻿' + lines.map((l) => l.map((c) => typeof c === 'number' ? Math.round(c) : '"' + String(c).replace(/"/g, '""') + '"').join(';')).join('\r\n'); const r = API.exportCsv(p, csv); if (r && r.then) r.then(() => toast('File CSV disimpan')).catch((e) => toast(e.message || 'Unduh dibatalkan', true)); }
};
window.A = A;
KONSULTAN.set = (p) => { sel.kon = Object.assign({}, sel.kon || KONSULTAN.defaults(), p); render(); window.scrollTo(0, 0); };
KONSULTAN.save = () => { const nama = $('#kNama').value.trim(), klien = $('#kKlien').value.trim(); if (!nama) return toast('Isi nama proyek', true); const b = KONSULTAN.toProject(sel.kon, nama, klien); run(async () => { const p = await API.saveProject(b); sel.pid = p.id; sel.kon = null; view = S.user.role === 'owner' ? 'project' : 'rab'; }, 'Proyek dibuat dengan RAB awal. Admin bisa merapikan angkanya di menu RAB.'); };

/* ---------- potongan tampilan ---------- */
const pill = (t, c) => '<span class="pill ' + c + '">' + esc(t) + '</span>';
const kpi = (l, v, extra, cls) => '<div class="kpi ' + (cls || '') + '"><span class="l">' + esc(l) + '</span><span class="v">' + v + '</span>' + (extra ? '<span class="tiny muted">' + esc(extra) + '</span>' : '') + '</div>';
const bar = (x) => '<div class="bar"><span style="width:' + Math.round(Math.max(0, Math.min(1, x)) * 100) + '%"></span></div>';
const card = (inner, cls) => '<div class="card ' + (cls || '') + '">' + inner + '</div>';
const todo = (t, s, go, bg, ink) => '<button class="todo" onclick="' + go + '"><span class="ico" style="background:' + bg + ';color:' + ink + '"><i style="background:' + ink + '"></i></span><span class="col grow"><span class="t">' + esc(t) + '</span><span class="s">' + esc(s) + '</span></span>' + I.chev + '</button>';
const hdrWho = (right) => '<div class="hdr"><div class="who"><span class="avatar">' + initials(S.user.name) + '</span><span class="col" style="gap:0"><span class="greet">' + salam() + '</span><span class="name">' + esc(S.user.name) + '</span></span></div>' + (right || '') + '</div>';
const hdrTitle = (title, sub, right) => '<div class="hdr"><span class="col" style="gap:0"><span class="date">' + esc(sub || hariIni()) + '</span><span class="title">' + esc(title) + '</span></span>' + (right || '') + '</div>';
function navBar(items, fab) {
  const b = (it) => '<button class="' + (view === it[0] ? 'on' : '') + '" onclick="A.go(\'' + it[0] + '\')">' + it[2] + esc(it[1]) + '</button>';
  const f = '<button class="fab ' + (view === fab[0] ? 'on' : '') + '" aria-label="' + esc(fab[1]) + '" onclick="A.go(\'' + fab[0] + '\')">' + fab[2] + (fab[3] ? '<span class="badge">' + fab[3] + '</span>' : '') + '</button>';
  return '<nav class="nav">' + b(items[0]) + b(items[1]) + f + b(items[2]) + b(items[3]) + '</nav>';
}
function projPicker() { if (S.projects.length < 2) return ''; return '<div class="chips">' + S.projects.map((p) => '<button class="chip ' + (p.id === sel.pid ? 'on' : '') + '" onclick="A.pick(\'' + p.id + '\')">' + esc(p.name) + '</button>').join('') + '</div>'; }
const statusPill = (n) => n.status === 'pending' ? pill('Menunggu Admin', 'warn') : n.status === 'owner' ? pill('Menunggu Owner', 'blue') : n.status === 'approved' ? pill('Disetujui', 'ok') : pill('Ditolak', 'bad');
const photo = (ref, cls) => '<a href="' + API.photoUrl(ref) + '" target="_blank"><img class="' + (cls || 'thumb') + '" src="' + API.photoUrl(ref) + '" alt=""></a>';
function notaCard(n, actions) {
  const chk = money() && n.check ? '<div class="small" style="color:' + (n.check.flag === 'tinggi' ? 'var(--bad)' : n.check.flag === 'rendah' ? 'var(--warn)' : 'var(--ok)') + '">' + esc(n.check.item) + ': ' + rp(n.check.unit) + ' vs pasar ' + rp(n.check.market) + ' (' + (n.check.diff > 0 ? '+' : '') + pct(n.check.diff) + ') · ' + n.check.flag + (n.overMarket > 0 ? ' · kelebihan ' + rp(n.overMarket) : '') + '</div>' : (money() && !n.qty ? '<div class="tiny muted">tanpa pembanding harga pasar</div>' : '');
  return card('<div class="row between"><div class="col grow"><b>' + esc(n.desc || n.type) + '</b><span class="small muted">' + esc(n.name) + ' · ' + esc(n.shop || '—') + ' · ' + tgl(n.ts) + '</span></div><b>' + rp(n.amount) + '</b></div>' + chk + (n.note ? '<div class="small" style="color:var(--bad)">Catatan: ' + esc(n.note) + '</div>' : '') + '<div class="row between wrap">' + photo(n.photo) + (actions ? '<div class="row">' + actions + '</div>' : statusPill(n)) + '</div>');
}
function psak(p) {
  const C = S.config, s = p.summary, K = s.contract; const dpInv = S.invoices.find((i) => i.projectId === p.id && i.termin === 0 && i.status === 'paid'); const potDP = S.invoices.filter((i) => i.projectId === p.id && i.termin > 0 && i.status !== 'void').reduce((a, i) => a + i.potDP, 0);
  const rows = [['Pendapatan diakui', 'progres terverifikasi ' + pct(s.verified) + ' × kontrak', s.revenue, 1], ['Beban kontrak', 'nota yang disetujui', -s.spent, 0], ['Laba kotor sampai sekarang', '', s.revenue - s.spent, 1], ['Kas proyek', 'kas awal + DP + termin − biaya', s.kas, 1], ['Piutang tagihan', 'invoice terkirim belum dibayar', s.receivable, 0], ['Retensi ditahan klien', '', S.invoices.filter((i) => i.projectId === p.id && i.status !== 'void').reduce((a, i) => a + i.retensi, 0), 0], ['Liabilitas kontrak (sisa DP)', 'DP yang belum dipotong', dpInv ? K * p.dp - potDP : 0, 0], ['Proyeksi laba bersih akhir', 'setelah kantor ' + pct(C.overhead) + ', bunga ' + pct(C.bunga) + ', PPh ' + pct(C.pph), s.labaAkhir, 1]];
  return card('<h3>Laporan keuangan proyek (PSAK 72)</h3><div class="list">' + rows.map((r) => '<div class="row between"><div class="col" style="gap:0"><span class="' + (r[3] ? 'b' : '') + '">' + r[0] + '</span><span class="tiny muted">' + r[1] + '</span></div><span class="' + (r[3] ? 'b' : '') + '">' + sh(r[2]) + '</span></div>').join('') + '</div><button class="btn ghost sm" onclick="A.exportCsv()">Unduh Excel (CSV)</button>');
}

/* ---------- layar masuk ---------- */
function loginView() {
  const roles = [['owner', 'Owner', 'semua angka'], ['admin', 'Admin', 'finance'], ['mandor', 'Mandor', 'lapangan']]; sel.role = sel.role || 'owner';
  const warn = S && S.setupMissing ? '<div class="card warn" style="padding:10px 12px"><span class="small">Data awal belum ada. Minta Claude menyiapkan data awal (config, matriks harga, proyek contoh).</span></div>' : '';
  return '<div class="login"><form class="card" onsubmit="A.login(event)"><div class="row"><span class="avatar" style="border-radius:14px">BP</span><div class="col" style="gap:0"><h1>Buku Proyek</h1><span class="small muted">Masuk sebagai</span></div></div>' + warn + '<div class="roles">' + roles.map((r) => '<button type="button" class="' + (sel.role === r[0] ? 'on' : '') + '" onclick="A.setRole(\'' + r[0] + '\')">' + r[1] + '<span>' + r[2] + '</span></button>').join('') + '</div><div class="field"><label>Password ' + esc(roles.find((r) => r[0] === sel.role)[1]) + '</label><input id="pw" type="password" autocomplete="current-password" required></div><button class="btn full">Masuk</button><span class="tiny muted">Aplikasi internal. Password diganti dari Menu setelah masuk.</span></form></div>';
}

/* ---------- OWNER ---------- */
function ownerHome() {
  const ps = S.projects, C = S.config;
  const tot = ps.reduce((a, p) => { const s = p.summary; return { k: a.k + s.contract, kas: a.kas + s.kas, laba: a.laba + s.labaAkhir, rec: a.rec + s.receivable, ready: a.ready + (p.termins || []).filter((t) => !S.invoices.some((i) => i.projectId === p.id && i.termin === t.n && i.status !== 'void') && s.verified + 1e-9 >= t.atProgress).reduce((x, t) => x + t.pct * s.contract, 0) }; }, { k: 0, kas: 0, laba: 0, rec: 0, ready: 0 });
  const pend = S.notas.filter((n) => n.status === 'owner'), unver = S.reports.filter((r) => !r.verified).length, hadir = S.attendance.filter((a) => a.ts.slice(0, 10) === today() && a.type === 'masuk').reduce((a, x) => a + (x.workers || 0), 0);
  const todos = [];
  if (pend.length) todos.push(todo(pend.length + ' nota di atas ' + sh(C.approvalLimit) + ' menunggu Bapak', pend.map((n) => n.desc + ' ' + sh(n.amount)).join(', '), "A.go('approve')", 'var(--badbg)', 'var(--bad)'));
  const risk = ps.reduce((a, p) => a.concat((p.vos || []).filter((v) => v.status === 'risk')), []); if (risk.length) todos.push(todo(risk.length + ' pekerjaan tambah dikerjakan tanpa persetujuan klien', risk.map((v) => v.desc).join(', '), "A.go('tambahkurang')", 'var(--badbg)', 'var(--bad)'));
  if (tot.ready > 0) todos.push(todo('Termin siap ditagih ' + sh(tot.ready), 'progres terverifikasi sudah mencapai syarat', "A.go('termin')", 'var(--okbg)', 'var(--ok)'));
  if (unver) todos.push(todo(unver + ' laporan mandor belum diverifikasi', 'Cek foto & progres, lalu verifikasi', "A.go('bukti')", 'var(--warnbg)', 'var(--warn)'));
  const pcard = (p) => { const s = p.summary; const costPct = s.contract ? Math.min(100, Math.round(s.spent / s.contract * 100)) : 0; const ok = s.labaAkhir >= 0; return '<button class="pcard" onclick="A.pick(\'' + p.id + '\',\'project\')"><span class="chip ' + zoneCls(s.zone) + ' pill"><i></i>' + esc(s.zone) + '</span><span class="col" style="gap:0"><b style="font-size:16px">' + esc(p.name) + '</b><span class="tiny muted">' + esc(p.client) + '</span></span><span class="col"><span class="row between tiny muted"><span>Progres ' + Math.round(s.verified * 100) + '%</span><span>Biaya ' + costPct + '%</span></span><span class="pbar"><span style="width:' + Math.round(s.verified * 100) + '%"></span><i style="left:' + costPct + '%"></i></span></span><span class="foot"><span class="tiny muted">' + (ok ? 'Proyeksi laba' : 'Proyeksi rugi') + '</span><b style="font-size:16px;color:' + (ok ? 'var(--ok)' : 'var(--bad)') + '">' + sh(s.labaAkhir) + '</b></span></button>'; };
  return hdrWho('<button class="iconbtn" aria-label="Persetujuan" onclick="A.go(\'approve\')">' + I.bell + (pend.length ? '<span class="dot"></span>' : '') + '</button>') +
    '<div class="hero"><div class="col" style="gap:4px"><span class="lbl">Kas perusahaan · semua proyek</span><span class="big">' + sh(tot.kas) + '</span><span class="sub">Proyeksi laba semua proyek <b style="color:' + (tot.laba >= 0 ? 'var(--lime)' : '#FFB4AE') + '">' + sh(tot.laba) + '</b></span></div><div class="minis"><button class="mini" onclick="A.go(\'termin\')"><span>Siap ditagih</span><b class="lime">' + sh(tot.ready) + '</b></button><button class="mini" onclick="A.go(\'termin\')"><span>Piutang</span><b>' + sh(tot.rec) + '</b></button><button class="mini" onclick="A.go(\'bukti\')"><span>Hadir hari ini</span><b>' + hadir + ' org</b></button></div></div>' +
    '<div class="quick"><button onclick="A.go(\'termin\')"><span class="circ lime">' + I.send + '</span>Tagih</button><button onclick="A.go(\'bukti\')"><span class="circ">' + I.cam + '</span>Cek bukti</button><button onclick="A.go(\'penawaran\')"><span class="circ">' + I.calc + '</span>Hitung</button><button onclick="A.go(\'laporan\')"><span class="circ">' + I.chart + '</span>Laporan</button></div>' +
    '<button class="todo" style="background:var(--lime)" onclick="A.go(\'penawaran\')"><span class="avatar" style="background:var(--green);color:var(--lime);border-radius:21px;width:42px;height:42px">K</span><span class="col grow" style="gap:0"><span class="t">Ada permintaan penawaran baru?</span><span class="s" style="color:#0B1410;opacity:.8">Tanya Konsultan: 6 pertanyaan, langsung dapat harga aman</span></span>' + I.chev + '</button>' +
    (todos.length ? '<div class="col" style="gap:8px">' + todos.join('') + '</div>' : card('<b>Tidak ada yang menunggu Bapak hari ini.</b>', 'ok')) +
    '<div class="sect"><h2>Proyek berjalan</h2><button onclick="A.go(\'project\')">Lihat semua</button></div>' +
    (ps.length ? '<div class="hscroll">' + ps.map(pcard).join('') + '</div>' : card('<span class="muted">Belum ada proyek.</span><button class="btn sm" onclick="A.newProject()">+ Proyek baru</button>')) +
    card('<h3>Kejadian terakhir</h3><div class="list">' + S.log.slice(0, 8).map((l) => '<div class="small"><b>' + esc(l.who) + '</b> ' + esc(l.text) + '<br><span class="tiny muted2">' + tgl(l.ts) + '</span></div>').join('') + '</div>');
}
function projectView() {
  const p = P(); if (!p) return card('Belum ada proyek'); const s = p.summary;
  return hdrTitle(p.name, esc(p.client) + ' · ' + esc(p.status), pill(s.zone, zoneCls(s.zone))) + projPicker() +
    '<div class="hero"><div class="col" style="gap:4px"><span class="lbl">Nilai kontrak (belum PPN)' + (s.vo ? ' · termasuk tambah-kurang ' + sh(s.vo) : '') + '</span><span class="big">' + sh(s.contract) + '</span><span class="sub">RAP ' + sh(s.rap) + ' · margin ' + p.buk + '% · proyeksi laba <b style="color:var(--lime)">' + sh(s.labaAkhir) + ' (' + pct(s.labaPct) + ')</b></span></div><div class="minis"><button class="mini"><span>Biaya disetujui</span><b>' + sh(s.spent) + '</b></button><button class="mini"><span>Kas proyek</span><b class="lime">' + sh(s.kas) + '</b></button><button class="mini"><span>Piutang</span><b>' + sh(s.receivable) + '</b></button></div></div>' +
    (p.offer ? card('<div class="row between"><b>Dari Konsultan Penawaran</b><span class="tiny muted">' + tgl(p.offer.ts) + '</span></div><span class="small">' + esc({ baru: 'Bangun baru', renov_besar: 'Renovasi besar', renov_kecil: 'Renovasi kecil', interior: 'Interior' }[p.offer.kategori]) + ' · ' + esc(p.offer.type) + ' ' + p.offer.area.toLocaleString('id-ID') + ' m² · ' + esc(p.offer.qual) + ' · tukang ' + esc(p.offer.tukang) + '</span><div class="row between small"><span>Batas rugi <b>' + sh(p.offer.floor) + '</b></span><span>Bersaing <b>' + sh(p.offer.bersaing) + '</b></span><span>Aman <b>' + sh(p.offer.aman) + '</b></span></div><span class="tiny muted">Syarat: ' + p.offer.terms.slice(0, 3).map(esc).join(' · ') + '</span>') : '') +
    (s.overMarket ? card('<b>Biaya di atas harga pasar ' + sh(s.overMarket) + '</b><span class="small">Nota yang disetujui dengan harga lebih mahal dari matriks. Laba turun sebesar ini.</span>', 'warn') : '') +
    card('<h3>Progres per pekerjaan</h3><div class="list">' + p.divisions.map((d) => '<div class="col"><div class="row between small"><span>' + esc(d.name) + '</span><b>' + (d.verified || 0) + '% ✓ <span class="muted2">/ lapor ' + d.progress + '%</span></b></div>' + bar((d.verified || 0) / 100) + '</div>').join('') + '</div>') +
    psak(p) + card('<h3>Riwayat</h3><div class="list">' + S.log.filter((l) => l.projectId === p.id).slice(0, 12).map((l) => '<div class="small"><b>' + esc(l.who) + '</b> ' + esc(l.text) + ' <span class="tiny muted2">' + tgl(l.ts) + '</span></div>').join('') + '</div>');
}
function approveView() {
  const C = S.config; const mine = S.user.role === 'owner' ? S.notas.filter((n) => n.status === 'owner') : S.notas.filter((n) => n.status === 'pending'); const done = S.notas.filter((n) => !mine.includes(n)).slice(-10).reverse();
  return hdrTitle('Persetujuan biaya', S.user.role === 'admin' ? 'Admin sampai ' + sh(C.approvalLimit) + ', lebih dari itu ke Owner' : 'Nota di atas ' + sh(C.approvalLimit) + ' dari Admin') +
    (mine.length ? mine.map((n) => notaCard(n, '<button class="btn danger sm" onclick="A.decide(\'' + n.id + '\',\'reject\')">Tolak</button><button class="btn sm" onclick="A.decide(\'' + n.id + '\',\'approve\')">' + (S.user.role === 'admin' && n.amount > C.approvalLimit ? 'Teruskan ke Owner' : 'Setujui') + '</button>')).join('') : card('<b>Tidak ada yang menunggu.</b>', 'ok')) +
    (done.length ? '<div class="sect"><h2>Sudah diputuskan</h2></div>' + done.map((n) => notaCard(n)).join('') : '');
}
function menuView() {
  const mods = S.user.role === 'mandor' ? [] : [['penawaran', 'Konsultan Penawaran', 'hitung harga aman sebelum menawar'], ['rab', 'RAB & biaya modal', 'rincian per pekerjaan, margin'], ['tambahkurang', 'Tambah-kurang', 'pekerjaan di luar kontrak'], ['harga', 'Matriks harga pasar', 'pembanding nota mandor'], ['bukti', 'Cek bukti & persetujuan', 'foto, absen, nota'], ['termin', 'Tagihan & termin', 'DP, termin, retensi'], ['laporan', 'Laporan keuangan', 'PSAK 72, unduh Excel']];
  return hdrTitle('Menu', esc(S.user.name) + ' · ' + S.user.role) + (mods.length ? '<div class="col" style="gap:8px">' + mods.map((m) => todo(m[1], m[2], "A.go('" + m[0] + "')", 'var(--okbg)', 'var(--ok)')).join('') + '</div>' : '') +
    '<form class="card" onsubmit="A.setPass(event)"><h3>Ganti password</h3><div class="field"><label>Password lama</label><input id="pw0" type="password" required></div><div class="field"><label>Password baru (min. 6)</label><input id="pw1" type="password" required minlength="6"></div><button class="btn ghost">Simpan</button></form>' +
    '<div class="note">' + I.lock + '<span>Owner melihat semua angka dan menyetujui biaya di atas ' + sh(S.config.approvalLimit) + '. Admin – Finance: RAB, matriks harga, nota, tagihan. Mandor: absen, lapor progres, kirim nota — tanpa angka uang.</span></div>' +
    '<button class="btn danger full" onclick="A.logout()">Keluar</button>';
}

function laporanView() {
  const tot = S.projects.reduce((a, p) => { const s = p.summary; return { rev: a.rev + s.revenue, spent: a.spent + s.spent, kas: a.kas + s.kas, laba: a.laba + s.labaAkhir }; }, { rev: 0, spent: 0, kas: 0, laba: 0 });
  return hdrTitle('Laporan keuangan', 'Semua proyek · PSAK 72') + '<div class="grid">' + kpi('Pendapatan diakui', sh(tot.rev), 'progres terverifikasi × kontrak', 'dark') + kpi('Beban kontrak', sh(tot.spent), 'nota disetujui') + kpi('Laba kotor', sh(tot.rev - tot.spent)) + kpi('Kas', sh(tot.kas)) + '</div>' +
    S.projects.map((p) => '<div class="sect"><h2>' + esc(p.name) + '</h2><button onclick="A.pick(\'' + p.id + '\',\'project\')">Detail</button></div>' + psak(p)).join('');
}

function buktiView() {
  const C = S.config; const pendN = S.user.role === 'owner' ? S.notas.filter((n) => n.status === 'owner') : S.notas.filter((n) => n.status === 'pending'); const reps = S.reports.filter((r) => !r.verified).slice().reverse(); const ab = S.attendance.filter((a) => a.ts.slice(0, 10) === today()).slice().reverse();
  const pname = (id) => (S.projects.find((p) => p.id === id) || {}).name || '';
  return hdrTitle('Cek bukti', 'Foto, lokasi & nota dari lapangan') +
    (pendN.length ? '<div class="sect"><h2>Nota menunggu ' + (S.user.role === 'owner' ? 'Bapak' : 'Admin') + '</h2></div>' + pendN.map((n) => notaCard(n, '<button class="btn danger sm" onclick="A.decide(\'' + n.id + '\',\'reject\')">Tolak</button><button class="btn sm" onclick="A.decide(\'' + n.id + '\',\'approve\')">' + (S.user.role === 'admin' && n.amount > C.approvalLimit ? 'Teruskan ke Owner' : 'Setujui') + '</button>')).join('') : '') +
    '<div class="sect"><h2>Laporan progres belum diverifikasi</h2></div>' + (reps.length ? reps.map((r) => { const p = S.projects.find((x) => x.id === r.projectId) || { divisions: [] }; return card('<div class="row between"><div class="col grow" style="gap:0"><b>' + esc(pname(r.projectId)) + ' · ' + esc(r.name) + '</b><span class="small">' + r.items.map((it) => esc((p.divisions[it.div] || {}).name) + ' → ' + it.pct + '%').join(', ') + '</span><span class="tiny muted">' + tgl(r.ts) + (r.note ? ' · ' + esc(r.note) : '') + '</span></div></div><div class="thumbs">' + r.photos.map((f) => photo(f)).join('') + '</div><button class="btn sm" onclick="sel.pid=\'' + r.projectId + '\';A.verify(\'' + r.id + '\')">Verifikasi progres</button>'); }).join('') : card('<b>Semua laporan sudah diverifikasi.</b>', 'ok')) +
    card('<h3>Absen hari ini</h3><div class="list">' + (ab.length ? ab.map((a) => '<div class="row between small"><div class="row">' + photo(a.photo).replace('class="thumb"', 'class="thumb" style="width:40px;height:40px"') + '<div class="col" style="gap:0"><b>' + esc(a.name) + ' · ' + a.type + ' ' + jam(a.ts) + '</b><span class="tiny muted2">' + esc(pname(a.projectId)) + (a.workers ? ' · ' + a.workers + ' tukang' : '') + '</span></div></div>' + (a.onSite ? pill('Di lokasi', 'ok') : a.distM == null ? pill('Tanpa GPS', 'grey') : pill(a.distM + ' m dari proyek', 'bad')) + '</div>').join('') : '<span class="muted small">Belum ada yang absen hari ini.</span>') + '</div>');
}
function voView() {
  const p = P(); if (!p) return hdrTitle('Tambah-kurang') + card('Belum ada proyek.'); sel.voKind = sel.voKind || 'plus';
  const ST = { ok: ['Disetujui klien', 'ok'], wait: ['Menunggu jawaban klien', 'warn'], risk: ['Dikerjakan tanpa persetujuan', 'bad'], void: ['Dibatalkan', 'grey'] }, order = { risk: 0, wait: 1, ok: 2, void: 3 };
  const vos = (p.vos || []).slice().sort((a, b) => order[a.status] - order[b.status]); const sum = (f) => vos.filter(f).reduce((a, v) => a + v.price, 0);
  const sgn = (v) => (v < 0 ? '− ' : '+ ') + sh(Math.abs(v));
  return hdrTitle('Tambah-kurang', p.name) + projPicker() +
    '<div class="hero"><div class="col" style="gap:4px"><span class="lbl">Perubahan kontrak disetujui klien</span><span class="big">' + sgn(sum((v) => v.status === 'ok')) + '</span><span class="sub">Nilai kontrak sekarang <b style="color:var(--lime)">' + sh(p.summary.contract) + '</b></span></div><div class="minis"><button class="mini"><span>Menunggu klien</span><b>' + sh(sum((v) => v.status === 'wait')) + '</b></button><button class="mini"><span>Tanpa persetujuan</span><b style="color:#FFB4AE">' + sh(sum((v) => v.status === 'risk')) + '</b></button><button class="mini"><span>Jumlah item</span><b>' + vos.length + '</b></button></div></div>' +
    (vos.length ? vos.map((v) => card('<div class="row between"><div class="col grow" style="gap:0"><b>' + esc(v.desc) + '</b><span class="tiny muted">' + (v.kind === 'plus' ? 'Pekerjaan tambah' : 'Pekerjaan kurang') + ' · biaya ' + rp(v.cost) + ' + margin ' + v.margin + '% · ' + tgl(v.ts) + (v.okBy ? ' · disetujui ' + esc(v.okBy) : '') + '</span></div><b style="color:' + (v.kind === 'minus' ? 'var(--bad)' : 'var(--ok)') + '">' + sgn(v.price) + '</b></div><div class="row between wrap">' + pill(ST[v.status][0], ST[v.status][1]) + (v.status === 'ok' || v.status === 'void' ? '' : '<span class="row"><button class="btn sm ghost" onclick="A.voStatus(\'' + v.id + '\',\'void\')">Batal</button><button class="btn sm" onclick="A.voStatus(\'' + v.id + '\',\'ok\')">Disetujui klien</button></span>') + '</div>', v.status === 'risk' ? 'bad' : '')).join('') : card('<span class="muted">Belum ada pekerjaan tambah-kurang.</span>')) +
    card('<h3>Catat pekerjaan tambah / kurang</h3><div class="chips"><button class="chip ' + (sel.voKind === 'plus' ? 'on' : '') + '" onclick="A.setVoKind(\'plus\')">Tambah</button><button class="chip ' + (sel.voKind === 'minus' ? 'on' : '') + '" onclick="A.setVoKind(\'minus\')">Kurang</button></div><div class="field"><label>Uraian</label><input id="voDesc" placeholder="mis. Ganti keramik lantai 2 jadi granit 60×60"></div><div class="field"><label>Biaya modal (Rp)</label><input id="voCost" inputmode="numeric" placeholder="mis. 64000000"></div><div class="field"><label>Margin %</label><input id="voMargin" type="number" value="' + (p.buk || 15) + '"></div><label class="row small"><input type="checkbox" id="voRisk" style="width:22px;min-height:22px"> Sudah terlanjur dikerjakan (tanpa persetujuan)</label><span class="tiny muted">Harga ke klien = biaya + margin. Nilai kontrak hanya berubah setelah klien menyetujui.</span><button class="btn full" onclick="A.vo()">Simpan & kirim ke klien</button>');
}
function penawaranView() { sel.kon = sel.kon || KONSULTAN.defaults(); return hdrTitle('Konsultan Penawaran', 'Enam pertanyaan, langsung dapat harga aman') + KONSULTAN.view(sel.kon, S); }

/* ---------- ADMIN ---------- */
function adminDash() {
  const pend = S.notas.filter((n) => n.status === 'pending').length, unver = S.reports.filter((r) => !r.verified).length;
  const tot = S.projects.reduce((a, p) => ({ k: a.k + p.summary.contract, rec: a.rec + p.summary.receivable, kas: a.kas + p.summary.kas }), { k: 0, rec: 0, kas: 0 });
  return hdrTitle('Dasbor') + '<div class="grid">' + kpi('Nilai kontrak berjalan', sh(tot.k), S.projects.length + ' proyek', 'dark') + kpi('Kas', sh(tot.kas)) + kpi('Piutang', sh(tot.rec)) + kpi('Nota menunggu', String(pend), '', pend ? 'bad' : 'ok') + kpi('Laporan belum diverifikasi', String(unver), '', unver ? 'bad' : 'ok') + kpi('Matriks harga', S.matrix ? S.matrix.version : '—', S.matrix ? S.matrix.date : '') + '</div>' +
    '<div class="row wrap"><button class="btn sm" onclick="A.go(\'approve\')">Periksa nota (' + pend + ')</button><button class="btn sm ghost" onclick="A.go(\'lapangan\')">Verifikasi lapangan (' + unver + ')</button><button class="btn sm ghost" onclick="A.go(\'penawaran\')">Hitung penawaran baru</button><button class="btn sm ghost" onclick="A.newProject()">+ Proyek kosong</button></div>' +
    '<div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(260px,1fr))">' + S.projects.map((p) => { const s = p.summary; return card('<div class="row between"><b>' + esc(p.name) + '</b>' + pill(s.zone, zoneCls(s.zone)) + '</div><span class="small muted">' + esc(p.client) + ' · kontrak ' + sh(s.contract) + '</span>' + bar(s.verified) + '<div class="row between small"><span>Terverifikasi ' + pct(s.verified) + '</span><span>Laba ' + sh(s.labaAkhir) + '</span></div><button class="btn sm ghost" onclick="A.pick(\'' + p.id + '\',\'rab\')">Buka RAB</button>'); }).join('') + '</div>' +
    card('<h3>Kejadian terakhir</h3><div class="list">' + S.log.slice(0, 12).map((l) => '<div class="small"><b>' + esc(l.who) + '</b> ' + esc(l.text) + ' <span class="tiny muted2">' + tgl(l.ts) + '</span></div>').join('') + '</div>');
}
function rabView() {
  const p = P(); if (!p) return hdrTitle('RAB & penawaran') + '<button class="btn" onclick="A.newProject()">+ Proyek baru</button>'; const s = p.summary, C = S.config;
  const rows = p.divisions.map((d, i) => '<tr><td><input class="sm" id="dn' + i + '" value="' + esc(d.name) + '"></td><td><input class="sm num" id="dr' + i + '" inputmode="numeric" value="' + Math.round(d.rap).toLocaleString('id-ID') + '" oninput="A.bukPreview()"></td><td class="num">' + rp(d.rap * (1 + p.buk / 100)) + '</td><td class="num">' + (s.rap ? pct(d.rap / s.rap) : '—') + '</td></tr>').join('');
  return hdrTitle('RAB & penawaran', hariIni(), '<button class="btn sm ghost" onclick="A.newProject()">+ Proyek baru</button>') + projPicker() +
    card('<div class="grid"><div class="field"><label>Nama proyek</label><input class="sm" id="pname" value="' + esc(p.name) + '"></div><div class="field"><label>Klien</label><input class="sm" id="pclient" value="' + esc(p.client) + '"></div><div class="field"><label>Alamat</label><input class="sm" id="paddr" value="' + esc(p.address || '') + '"></div><div class="field"><label>Status</label><select class="sm" id="pstatus">' + ['penawaran', 'kontrak', 'berjalan', 'selesai'].map((x) => '<option ' + (p.status === x ? 'selected' : '') + '>' + x + '</option>').join('') + '</select></div><div class="field"><label>Titik proyek (lat)</label><input class="sm" id="plat" value="' + (p.lat ?? '') + '"></div><div class="field"><label>Titik proyek (lng)</label><input class="sm" id="plng" value="' + (p.lng ?? '') + '"></div><div class="field"><label>Kas awal proyek</label><input class="sm" id="kas" inputmode="numeric" value="' + Math.round(p.kasAwal || 0).toLocaleString('id-ID') + '"></div></div><span class="tiny muted">Titik proyek dipakai untuk mengecek absen mandor (radius ' + C.siteRadiusM + ' m). Dari Google Maps: klik kanan → salin koordinat.</span>') +
    card('<h3>Biaya modal per pekerjaan (RAP) — tidak pernah dikirim ke klien</h3><div class="scroll"><table><tr><th>Pekerjaan</th><th class="num">RAP (Rp)</th><th class="num">Harga ke klien</th><th class="num">Bobot</th></tr>' + rows + '<tr><td class="b">JUMLAH</td><td class="num b">' + rp(s.rap) + '</td><td class="num b">' + rp(s.contract) + '</td><td class="num">100%</td></tr></table></div><button class="btn sm ghost" onclick="A.addDiv()">+ Tambah pekerjaan</button>') +
    card('<h3>Pengaman laba</h3><div class="row wrap"><div class="field"><label>Margin di RAB (BUK %) — minimal ' + s.floorBuk + '%</label><input class="sm" id="buk" type="number" min="' + s.floorBuk + '" max="25" value="' + p.buk + '" oninput="A.bukPreview()" style="width:110px"></div><div id="bukOut" class="grow">Harga ke klien <b>' + sh(s.contract) + '</b> · laba bersih <b>' + pct(s.net) + '</b> ' + pill(s.zone, zoneCls(s.zone)) + '</div></div><span class="tiny muted">Dari setiap Rp 100 harga: kantor ' + (C.overhead * 100) + ', bunga ' + (C.bunga * 100) + ', PPh final ' + (C.pph * 100) + ' → di bawah ' + s.floorBuk + '% pasti rugi.</span><button class="btn" onclick="A.saveRab()">Simpan RAB</button>') +
    card('<h3>Kirim</h3><button class="btn sm ghost" onclick="A.exportCsv()">Unduh ringkasan (CSV)</button><span class="tiny muted">Versi klien tanpa RAP dan margin; versi bank dengan struktur biaya. (PDF menyusul.)</span>');
}
function matrixView() {
  if (!S.matrix) return hdrTitle('Matriks harga') + card('Matriks belum ada.');
  return hdrTitle('Matriks harga ' + S.matrix.version, 'Patokan: harga pasar terbaru · nota dibandingkan dengan kolom "Wajar"') + card('<div class="scroll"><table><tr><th>Bahan / upah</th><th>Sat</th><th class="num">Rendah</th><th class="num">Wajar</th><th class="num">Tinggi</th><th>Sumber</th><th></th></tr>' +
    S.matrix.items.map((it) => '<tr><td class="b">' + esc(it.name) + '<br><span class="tiny muted2">' + esc(it.date) + '</span></td><td>' + esc(it.unit) + '</td><td><input class="sm num" id="ml-' + it.key + '" value="' + it.low + '" style="width:100px"></td><td><input class="sm num b" id="mt-' + it.key + '" value="' + it.typ + '" style="width:110px"></td><td><input class="sm num" id="mh-' + it.key + '" value="' + it.high + '" style="width:100px"></td><td><input class="sm" id="ms-' + it.key + '" value="' + esc(it.src) + '" style="width:160px"></td><td><button class="btn sm ghost" onclick="A.saveMx(\'' + it.key + '\')">Simpan</button></td></tr>').join('') + '</table></div>');
}
function lapanganView() {
  const p = P(); if (!p) return hdrTitle('Laporan lapangan'); const reps = S.reports.filter((r) => r.projectId === p.id).slice().reverse(); const abs = S.attendance.filter((a) => a.projectId === p.id).slice().reverse().slice(0, 14);
  return hdrTitle('Laporan lapangan', p.name) + projPicker() + (reps.length ? reps.map((r) => card('<div class="row between"><div class="col grow"><b>' + esc(r.name) + ' · ' + tgl(r.ts) + '</b><span class="small">' + r.items.map((it) => esc((p.divisions[it.div] || {}).name) + ' → ' + it.pct + '%').join(', ') + '</span>' + (r.note ? '<span class="small muted">' + esc(r.note) + '</span>' : '') + '</div>' + (r.verified ? pill('Diverifikasi', 'ok') : '<button class="btn sm" onclick="A.verify(\'' + r.id + '\')">Verifikasi</button>') + '</div><div class="thumbs">' + r.photos.map((f) => photo(f)).join('') + '</div>')).join('') : card('<span class="muted">Belum ada laporan.</span>')) +
    card('<h3>Absensi mandor</h3><div class="list">' + (abs.length ? abs.map((a) => '<div class="row between small"><div class="row">' + photo(a.photo, 'thumb').replace('class="thumb"', 'class="thumb" style="width:40px;height:40px"') + '<div class="col" style="gap:0"><b>' + esc(a.name) + ' · ' + a.type + '</b><span class="tiny muted2">' + tgl(a.ts) + (a.workers ? ' · ' + a.workers + ' tukang' : '') + '</span></div></div>' + (a.onSite ? pill('Di lokasi', 'ok') : a.distM == null ? pill('Tanpa GPS', 'grey') : pill(a.distM + ' m dari proyek', 'bad')) + '</div>').join('') : '<span class="muted small">Belum ada absen.</span>') + '</div>');
}
function tagihanView() {
  const p = P(); if (!p) return hdrTitle('Tagihan & termin'); const s = p.summary, invs = S.invoices.filter((i) => i.projectId === p.id);
  const row = (t, inv) => { const can = !inv && (t.n === 0 ? p.status !== 'penawaran' : s.verified + 1e-9 >= t.atProgress); return '<div class="row between wrap"><div class="col" style="gap:0"><b>' + esc(t.label) + '</b><span class="small muted">' + (t.n === 0 ? 'DP ' + (p.dp * 100) + '% saat tanda tangan' + (p.status === 'penawaran' ? ' (ubah status proyek dari "penawaran" dulu)' : '') : 'cair saat progres terverifikasi ≥ ' + Math.round(t.atProgress * 100) + '% (sekarang ' + Math.round(s.verified * 100) + '%)') + '</span></div>' + (inv ? '<div class="col right"><b>' + rp(inv.transfer) + '</b>' + (inv.status === 'paid' ? pill('Dibayar ' + tgl(inv.paidAt), 'ok') : '<button class="btn sm ghost" onclick="A.paid(\'' + inv.id + '\')">Tandai dibayar</button>') + '</div>' : '<button class="btn sm" ' + (can ? '' : 'disabled') + ' onclick="A.invoice(' + t.n + ')">Buat tagihan</button>') + '</div>'; };
  const terms = [{ n: 0, label: 'Uang muka (DP)', atProgress: 0 }].concat(p.termins);
  return hdrTitle('Tagihan & termin', p.name) + projPicker() + card('<div class="list">' + terms.map((t) => row(t, invs.find((i) => i.termin === t.n && i.status !== 'void'))).join('') + '</div>') +
    invs.filter((i) => i.termin > 0).map((i) => card('<h3>' + esc(i.label) + ' · progres ' + i.progressPct + '%</h3><div class="list small">' + [['Nilai pekerjaan (bruto)', i.bruto], ['− Potongan uang muka', -i.potDP], ['− Retensi', -i.retensi], ['Tagihan bersih', i.net], ['+ PPN', i.ppn], ['− PPh final (dipotong klien)', -i.pph], ['Ditransfer klien', i.transfer]].map((r) => '<div class="row between"><span>' + r[0] + '</span><b>' + rp(r[1]) + '</b></div>').join('') + '</div>')).join('') + psak(p);
}

/* ---------- MANDOR ---------- */
function mandorHome() {
  const p = P(); if (!p) return hdrTitle('Pagi, ' + S.user.name) + card('Belum ada proyek yang ditugaskan.');
  const ab = S.attendance.filter((a) => a.projectId === p.id && a.ts.slice(0, 10) === today()); const masuk = ab.find((a) => a.type === 'masuk'), pulang = ab.find((a) => a.type === 'pulang');
  const items = S.reports.filter((r) => r.projectId === p.id).map((r) => ({ ts: r.ts, t: 'Laporan progres · ' + r.items.map((it) => (p.divisions[it.div] || {}).name + ' ' + it.pct + '%').join(', '), s: r.photos.length + ' foto', pill: r.verified ? pill('Diverifikasi', 'ok') : pill('Menunggu verifikasi', 'warn') }))
    .concat(S.notas.filter((n) => n.projectId === p.id).map((n) => ({ ts: n.ts, t: 'Nota · ' + (n.desc || n.type) + ' ' + rp(n.amount), s: n.note || '', pill: statusPill(n) }))).sort((a, b) => b.ts.localeCompare(a.ts)).slice(0, 20);
  const abCard = masuk ? '<div class="card ' + (masuk.onSite ? 'ok' : 'warn') + '" style="border-radius:24px;padding:18px"><span class="small b" style="opacity:.85">Absensi saya</span><b style="font-size:22px;line-height:1.2">✓ Masuk ' + jam(masuk.ts) + (masuk.onSite ? ' di lokasi' : ' — ' + (masuk.distM == null ? 'tanpa GPS' : masuk.distM + ' m dari proyek')) + '</b><span class="small" style="opacity:.85">' + (masuk.workers ? masuk.workers + ' tukang hadir' : '') + (pulang ? ' · pulang ' + jam(pulang.ts) : '') + '</span>' + (!pulang ? '<button class="btn white" onclick="A.go(\'absen\')">Absen pulang</button>' : '') + '</div>'
    : '<div class="card dark" style="border-radius:24px;padding:18px"><span class="small b" style="color:#A9C7B8">Absensi saya</span><b style="font-size:22px;line-height:1.2">Belum absen hari ini</b><span class="small" style="color:#A9C7B8">Selfie + lokasi. Laporan progres hanya bisa dikirim setelah absen di lokasi.</span><button class="btn lime" onclick="A.go(\'absen\')">Absen masuk sekarang</button></div>';
  return hdrTitle('Pagi, ' + S.user.name.replace(/^Pak |^Bu /, ''), hariIni(), pill('Mandor · ' + p.name, 'warn')) + abCard +
    (API.canUpload() ? '' : card('<b>Unggah foto tidak aktif</b><span class="small">Akun ini hanya punya akses "lihat". Minta Owner membagikan halaman ini dengan akses "dapat mengedit".</span>', 'warn')) +
    '<div class="tiles"><button class="tile lime" onclick="A.go(\'lapor\')">' + I.cam + '<span class="col" style="gap:0"><b class="l">Lapor progres</b><span class="s">foto pekerjaan hari ini</span></span></button><button class="tile" onclick="A.go(\'nota\')">' + I.nota + '<span class="col" style="gap:0"><b class="l">Kirim nota</b><span class="s">belanja & upah</span></span></button></div>' +
    card('<b style="font-size:15px">Laporan saya</b><div class="list">' + (items.length ? items.map((x) => '<div class="row between"><span class="col grow" style="gap:0"><b class="small">' + esc(x.t) + '</b><span class="tiny muted">' + tgl(x.ts) + (x.s ? ' · ' + esc(x.s) : '') + '</span></span>' + x.pill + '</div>').join('') : '<span class="muted small">Belum ada kiriman.</span>') + '</div>') +
    '<div class="note">' + I.lock + '<span>Akun mandor: absen, lapor progres, kirim nota, dan foto untuk proyek ' + esc(p.name) + '. Nilai kontrak, harga RAB, dan keuangan hanya untuk Owner dan Admin.</span></div>';
}
function absenView() {
  const p = P(); const ab = S.attendance.filter((a) => a.projectId === p.id && a.ts.slice(0, 10) === today()); const type = ab.some((a) => a.type === 'masuk') ? 'pulang' : 'masuk';
  return hdrTitle('Absen ' + type, p.name) + card('<div class="field"><label>1 · Selfie di lokasi</label><input id="selfie" type="file" accept="image/*" capture="user" onchange="this.nextElementSibling.src=window.URL.createObjectURL(this.files[0])"><img class="photo" alt="" style="margin-top:8px"></div>' + (type === 'masuk' ? '<div class="field"><label>2 · Jumlah tukang hadir hari ini</label><input id="workers" type="number" inputmode="numeric" min="0" placeholder="mis. 14"></div>' : '<input id="workers" type="hidden" value="0">') + '<span class="small muted">Lokasi GPS diambil otomatis saat tombol ditekan. Izinkan akses lokasi di browser.</span><button id="btnAbsen" class="btn lime full" onclick="A.absen(\'' + type + '\')">Kirim absen</button>');
}
